    monthly_mortgage = (price_home - buy_down_payment) * (buy_interest_rate / 12) / (1 - (1 + (buy_interest_rate / 12)) ** (-buy_years * 12))
    total_cost_buy = (monthly_mortgage * buy_years * 12) + buy_down_payment
    total_cost_rent = rent_monthly * (buy_years * 12)

    if total_cost_buy < total_cost_rent:
        return "Buy is cheaper"
    elif total_cost_rent < total_cost_buy:
        return "Rent is cheaper"
    else:
        return "Costs are equal"

